-- 24 Oct 2026: the Step-by-step Scheduler (#/stepper).
--
-- 1. order_install_alerts: the INSTALLATION ALERTS text the agent posts to the Installation alerts
--    group, one row per order. That text was built on the fly by ingestion-agent/order_alerts.collect()
--    and never stored, so the app had nothing to show. The agent now upserts it whenever it builds the
--    installation digest (notify._alert_digest); a one-off backfill filled the upcoming orders.
--    Readable by signed-in users; written only by the agent's service role.
create table if not exists public.order_install_alerts (
  order_id   text primary key,
  version_no integer,
  lines      jsonb not null default '[]'::jsonb,   -- ["• Blackout: 4", "• Bedroom — ... — note", ...]
  built_at   timestamptz not null default now(),
  source     text not null default 'agent'
);
alter table public.order_install_alerts enable row level security;
drop policy if exists order_install_alerts_read on public.order_install_alerts;
create policy order_install_alerts_read on public.order_install_alerts for select to authenticated using (true);
revoke all on public.order_install_alerts from anon;
grant select on public.order_install_alerts to authenticated;

-- 2. The stepper's timing rules and crew list, copied from the Schedule skill (rules.json and
--    roster_seed.json, 24 Oct 2026). sched_settings is readable by every signed-in user already.
insert into public.sched_settings(key, value, updated_by) values
  ('stepper_rules',  $j${"_about":"Timing rules the user gave on 28 Sep 2026. build_facts.py and sched_eval.py read them; change a number here, not in code.","blind_min":20,"curtain_1layer_min":30,"curtain_2layer_min":45,"standard_width_cm":350,"width_step_cm":20,"width_step_min":1,"pelmet_min":30,"flex_track_min":20,"scaffold_height_cm":350,"scaffold_order_min":60,"scaffold_extra_window_min":45,"motor_per_window_min":30,"removal_min":15,"cassette_min":0,"isr_flat_min":60,"work_start":"09:00","work_end":"18:00","villa_work_end":"20:00","free_shift_earlier_min":120,"free_shift_later_min":60,"odd_time_before":"08:00","odd_time_after":"18:00","tall_flag_cm":320,"travel":{"buffer_min":15,"same_place_km":0.3,"same_place_min":5,"bands":[{"max_km":8,"road_factor":1.45,"kmh":32},{"max_km":25,"road_factor":1.35,"kmh":45},{"max_km":60,"road_factor":1.25,"kmh":65},{"max_km":null,"road_factor":1.15,"kmh":90}]}}$j$::jsonb,  'claude 2026-10-24'),
